  }

  .larson-scanner__commands button:nth-child(2) {
    border-right: 0;
  }

  .larson-scanner__commands button:last-child {
    grid-column: 1 / -1;
    border-top: 1px solid var(--larson-line-bright);
  }

  .larson-scanner__controls > section {
    padding: 24px 16px;
  }

  .larson-scanner__patterns,
  .larson-scanner__colors {
    grid-template-columns: 1fr;
  }

  .larson-scanner__patterns button {
    border-right: 0;
  }

  .larson-scanner__patterns button:nth-last-child(2) {
    border-bottom: 1px solid var(--larson-line);
  }

  .larson-scanner__footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 7px;
  }

  .larson-scanner__footer > div {
    width: 100%;
    justify-content: space-between;
  }
}

@media (prefers-reduced-motion: reduce) {
  .larson-scanner *,
  .larson-scanner *::before,
  .larson-scanner *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}
